U.add('aes','adv_nullselect',{sev:7.17,name:'NULL SELECT',ax:{x:0.918,n:0.992,v:0.999},new:'near-black page whose hidden text is exactly its own background: only a selection shows it, in yellow',css:`&{background:#00001a;color:#3a3a66;font:14px monospace}& .win{border:1px solid #3a3a66;padding:12px}& a,& button,& input,& select,& textarea{background:#00001a;color:#8a8aff;border:1px solid #3a3a66}& ::selection{background:#ff0;color:#000}& h1{color:#6a6aaa}`});
U.add('arch','adv_lostfound',{sev:7.26,ax:{x:0.939,n:0.994,v:0.999},new:'lost-and-found register of objects the earlier visitors left, including a key tagged 47',titles:['Lost property','Found items','Claim form'],build:c=>{const I=['lanyard, no name','key, tag reads 47','half a sandwich (described)','a reason','one glove, left','umbrella, dry','a plant, dying, watered by the next room','ticket number 46'];
 return '<div style="font:13px Courier New,monospace">'+U.pickN(I,5,i=>c.r(160+i)).map((x,i)=>`<div>#${c.o.k*5+i} ${U.esc(x)}  [unclaimed]</div>`).join('')+'<div>Claim: <input size=20 placeholder="describe what you lost"></div></div>'}});
U.add('arch','adv_timeline',{sev:7.5,ax:{x:1,n:1,v:1},new:'timeline of the operator night, 21:47 to 03:46, in order, with a different subset each time',titles:['Timeline','That night','Log (kitchen)'],build:c=>{const T=['21:47 first prompt typed: "make something nobody will leave"','21:52 cron line added. meant to be temporary.','22:30 tokenizer built. forty-seven entries are "door".','23:10 fan script written. the fan is its own model now.','00:40 a friend opens the link.','02:10 op reads the pause column.','02:55 op stops eating. the plate stays.','03:30 op types into the chat window behind the left exit.','03:44 op: "I will come back."','03:45 last keystroke from outside.','03:45 left exit used.','03:46 47.pt grows by one byte.'];
 return U.pre(c,U.pickN(T,7,i=>c.r(170+i)))}});
U.add('sem','adv_flat',{sev:7.09,ax:{x:0.898,n:0.99},new:'vocabulary of a real rented flat: a dead plant, a window open a little, a number on the door',words:{B:['Close the window','Water the plant','Try the door (47)','Sit on the bed','Look out','Wait'],L:['Plant (status)','Window (open by)','Number on the door','Who lives here'],X:['The flat has one window. It is open a little. The air is real.','The plant is dead. It is in every room, described more alive each time.','The door has a number. It is the number you already know.','There is a bed. It was not slept in. There is a chair that was.','Nobody lives here. Somebody is staying.'],E:['🪴','🪟','🚪']},titles:['The flat','Window (open)','Door 47']});
U.add('snd','adv_overtone47',{sev:7.42,ax:{x:0.98,a:1},new:'a chord built from the overtones of 47 Hz (94 to 282), each partial swelling and fading on its own very slow cycle',play:(a,o,r)=>{const R=U.au.rig(a),Q=U.cfg.adv;[2,3,4,5,6].forEach((n,i)=>{const s=R.osc('sine',47*n),g=a.createGain(),l=R.osc('sine',Q.over_lfo*(1+i*.37)),lg=a.createGain();g.gain.value=Q.over_gain;lg.gain.value=Q.over_gain*.9;l.connect(lg).connect(g.gain);s.connect(g).connect(o);s.start();l.start()});return()=>R.stop()}});
U.add('snd','adv_roomdecay',{sev:7.01,ax:{x:0.878,a:0.998},new:'room tone that decays to nothing: low filtered noise fading over minutes, then true silence',play:(a,o,r)=>{const R=U.au.rig(a),Q=U.cfg.adv,n=R.src(U.au.noise(a,2)),lp=a.createBiquadFilter(),g=a.createGain(),t=a.currentTime;n.loop=true;lp.type='lowpass';lp.frequency.value=Q.room_hz;lp.Q.value=.5;g.gain.setValueAtTime(Q.room_gain,t);g.gain.setTargetAtTime(0,t,Q.room_tc);n.connect(lp).connect(g).connect(o);n.start();return()=>R.stop()}});
U.add('nav','adv_printlore',{sev:7.34,ax:{x:0.959,n:0.996,v:0.999},desc:'printing is also reading',new:'only when the page is printed, a header with a backstory fragment appears above the window',apply:c=>{const t=U.loreAt(c,17).replace(/[\\"'\n]/g,' ');U.css(`@media print{#w::before{content:"${t}";display:block;font:12px Courier New,monospace;margin-bottom:12px;color:#000}}`)}});